// AULA Token Manager
// Refreshes the OIDC access_token using the stored refresh_token.
//
// Required env var: AULA_REFRESH_TOKEN
//   Initial refresh token extracted from Scaarup HA-AULA integration.
//   After first successful refresh, subsequent tokens are stored in flow context.
//
// Outputs: msg.aula_token — valid AULA access token

const CLIENT_ID = '_99949a54b8b65423862aac1bf629599ed64231607a';
const TOKEN_URL = 'https://login.aula.dk/simplesaml/module.php/oidc/token.php';

(async function () {
    let tokenData = flow.get('aula_token_data') || {};
    const now = Date.now();

    // Reuse valid token — keep 60-second buffer to avoid last-second expiry races
    if (tokenData.access_token && tokenData.expires_at && tokenData.expires_at > now + 60000) {
        msg.aula_token = tokenData.access_token;
        node.status({ fill: 'green', shape: 'dot', text: 'Token OK' });
        node.send(msg);
        return;
    }

    // Prefer refresh token stored from last successful refresh; fall back to env var seed
    const refreshToken = tokenData.refresh_token || env.get('AULA_REFRESH_TOKEN');
    if (!refreshToken) {
        node.error('Missing AULA refresh token — set AULA_REFRESH_TOKEN env var.', msg);
        node.status({ fill: 'red', shape: 'ring', text: 'No refresh token' });
        return;
    }

    try {
        node.status({ fill: 'yellow', shape: 'ring', text: 'Refreshing token...' });

        const res = await fetch(TOKEN_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: new URLSearchParams({
                grant_type: 'refresh_token',
                refresh_token: refreshToken,
                client_id: CLIENT_ID
            }).toString()
        });

        if (!res.ok) {
            const txt = await res.text();
            throw new Error('HTTP ' + res.status + ': ' + txt.slice(0, 200));
        }

        const data = await res.json();
        if (!data.access_token) {
            throw new Error('No access_token in response: ' + JSON.stringify(data).slice(0, 200));
        }

        // Persist updated token data in flow context for next poll cycle
        tokenData = {
            access_token: data.access_token,
            refresh_token: data.refresh_token || refreshToken,
            expires_at: now + ((data.expires_in || 3600) * 1000)
        };
        flow.set('aula_token_data', tokenData);

        msg.aula_token = data.access_token;
        node.status({ fill: 'green', shape: 'dot', text: 'Token refreshed' });
        node.send(msg);
    } catch (err) {
        node.error('Token refresh failed: ' + err.message, msg);
        node.status({ fill: 'red', shape: 'ring', text: 'Refresh error' });
    }
})();

// AULA Message Poller
// Fetches all message threads and their messages from the AULA messaging API.
// Paginates automatically until all pages are retrieved.
//
// Input:  msg.aula_token — valid AULA access token (set by Token Manager)
// Output: msg.payload    — { timestamp, threadCount, unreadCount, threads[] }
//
// Optional env vars:
//   AULA_API_VERSION — API version (default: '22')

const API_VERSION = env.get('AULA_API_VERSION') || '22';
const BASE_URL = 'https://www.aula.dk/api/v' + API_VERSION + '/';
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:109.0) Gecko/20100101 Firefox/115.0';
const MAX_PAGES = 20; // Safety cap against runaway pagination

const token = msg.aula_token;
if (!token) {
    node.error('No AULA access token in msg.aula_token', msg);
    return;
}

async function aulaGet(method, extraParams) {
    const url = BASE_URL + '?method=' + method + (extraParams || '') +
                '&access_token=' + encodeURIComponent(token);
    const res = await fetch(url, { headers: { 'User-Agent': UA } });
    if (!res.ok) throw new Error(method + ' failed: HTTP ' + res.status);
    return res.json();
}

async function fetchAllThreads() {
    const threads = [];
    for (let page = 0; page < MAX_PAGES; page++) {
        const data = await aulaGet(
            'messaging.getThreads',
            '&sortOn=date&orderDirection=desc&page=' + page
        );
        if (!data.data || !data.data.threads) {
            throw new Error('Unexpected getThreads response on page ' + page);
        }
        const pageThreads = data.data.threads;
        threads.push.apply(threads, pageThreads);
        node.status({ fill: 'blue', shape: 'dot', text: 'Threads p' + page + ' (' + threads.length + ')' });
        if (pageThreads.length < 10) break; // AULA returns up to 10 per page; fewer = last page
    }
    return threads;
}

async function fetchMessagesForThread(threadId) {
    const messages = [];
    for (let page = 0; page < MAX_PAGES; page++) {
        const data = await aulaGet(
            'messaging.getMessagesForThread',
            '&threadId=' + threadId + '&page=' + page
        );
        if (!data.data || !data.data.messages || data.data.messages.length === 0) break;
        messages.push.apply(messages, data.data.messages);
        if (data.data.messages.length < 20) break; // Fewer than 20 = last page
    }
    return messages;
}

(async function () {
    try {
        node.status({ fill: 'blue', shape: 'ring', text: 'Fetching threads...' });
        const threads = await fetchAllThreads();

        const enrichedThreads = [];
        for (let i = 0; i < threads.length; i++) {
            node.status({ fill: 'blue', shape: 'dot', text: 'Messages ' + (i + 1) + '/' + threads.length });
            const messages = await fetchMessagesForThread(threads[i].id);
            enrichedThreads.push({ thread: threads[i], messages: messages });
        }

        const unreadCount = threads.filter(function (t) { return !t.read; }).length;
        msg.payload = {
            timestamp: new Date().toISOString(),
            threadCount: threads.length,
            unreadCount: unreadCount,
            threads: enrichedThreads
        };

        node.status({
            fill: 'green', shape: 'dot',
            text: threads.length + ' threads, ' + unreadCount + ' unread'
        });
        node.send(msg);
    } catch (err) {
        node.error('AULA poll error: ' + err.message, msg);
        node.status({ fill: 'red', shape: 'ring', text: err.message.slice(0, 50) });
    }
})();

// AULA MQTT Formatter
// Converts raw AULA thread data into per-topic MQTT messages.
// Returns an array so Node-RED sends each element as a separate message.
//
// Published topics (relative to PREFIX):
//   {PREFIX}          — full thread summary (retained)
//   {PREFIX}/status   — heartbeat with thread/unread counts (retained)
//   {PREFIX}/{id}     — per-thread detail with full message text (retained)
//   {PREFIX}/unread   — list of unread threads only (NOT retained)
//
// Optional env vars:
//   MQTT_TOPIC_PREFIX — topic prefix (default: 'aula/messages')

const PREFIX = env.get('MQTT_TOPIC_PREFIX') || 'aula/messages';
const data = msg.payload;

if (!data || !data.threads) {
    node.warn('No AULA thread data to publish');
    return null;
}

function stripHtml(html) {
    if (!html) return '';
    return String(html).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}

const out = [];

// 1. Status heartbeat — always published so HA sensors stay fresh
out.push({
    topic: PREFIX + '/status',
    payload: JSON.stringify({
        timestamp: data.timestamp,
        threadCount: data.threadCount,
        unreadCount: data.unreadCount
    }),
    qos: 1,
    retain: true
});

// 2. Summary of all threads
out.push({
    topic: PREFIX,
    payload: JSON.stringify({
        timestamp: data.timestamp,
        threadCount: data.threadCount,
        unreadCount: data.unreadCount,
        threads: data.threads.map(function (item) {
            return {
                id: item.thread.id,
                subject: item.thread.subject || '',
                read: item.thread.read || false,
                messageCount: item.messages.length
            };
        })
    }),
    qos: 1,
    retain: true
});

// 3. Per-thread detail with full message text
data.threads.forEach(function (item) {
    var t = item.thread;
    var formatted = item.messages
        .filter(function (m) { return !m.messageType || m.messageType === 'Message'; })
        .map(function (m) {
            var text = '';
            try {
                text = (m.text && m.text.html)
                    ? stripHtml(m.text.html)
                    : stripHtml(String(m.text || ''));
            } catch (e) { text = ''; }
            return {
                id: m.id,
                sendDateTime: m.sendDateTime,
                sender: (m.sender && m.sender.fullName) ? m.sender.fullName : 'Unknown',
                text: text,
                messageType: m.messageType || 'Message'
            };
        });
    out.push({
        topic: PREFIX + '/' + t.id,
        payload: JSON.stringify({
            id: t.id,
            subject: t.subject || '',
            read: t.read || false,
            messageCount: formatted.length,
            messages: formatted
        }),
        qos: 1,
        retain: true
    });
});

// 4. Unread-only list — not retained, useful for triggering HA automations
var unread = data.threads.filter(function (item) { return !item.thread.read; });
if (unread.length > 0) {
    out.push({
        topic: PREFIX + '/unread',
        payload: JSON.stringify({
            timestamp: data.timestamp,
            count: unread.length,
            threads: unread.map(function (item) {
                return { id: item.thread.id, subject: item.thread.subject || '' };
            })
        }),
        qos: 0,
        retain: false
    });
}

// Return array: Node-RED sends each element as a separate message to output 0
return [out];
